sys_rte_eb_entity_mapping.condition_script:
/* global input */
/*  Example Script 
 (function() {

         //step1: access the input variables
         if (input && input.temp.u_type == 'Disk') {
         //step2: return true/false 
            return true;
         }
         return false;

 })();
 */

(function(input) {
    const timeStamp = new Date().toISOString();
    const infoStr = 'OHS - ' + timeStamp + ' - Import to Temp - ';

    if (input) {
        gs.debug(infoStr + 'input good:\n' + JSON.stringify(input));

        if (input.x_hccc_hoc_ohs_initial_hira_import) {
            gs.debug(infoStr + 'input.x_hccc_hoc_ohs_initial_hira_import good:\n' +
                JSON.stringify(input.x_hccc_hoc_ohs_initial_hira_import));
        } else {
            gs.debug(infoStr + 'input.x_hccc_hoc_ohs_initial_hira_import bad');
        }
    } else {
        gs.debug(infoStr + 'input bad');
    }


    if (input && input.x_hccc_hoc_ohs_initial_hira_import &&
        input.x_hccc_hoc_ohs_initial_hira_import.u_position_code !== '') {

        gs.debug(infoStr + 'input.x_hccc_hoc_ohs_initial_hira_import:\n' +
            JSON.stringify(input.x_hccc_hoc_ohs_initial_hira_import)
        );
        return true;
    } else {
        return false;
    }
})(input);
